using Frameflow.Core;
using Frameflow.Media;

namespace Frameflow;
internal static class TimingCoreTests
{
    internal static void Run(string dir,Action<bool,string> check)
    {
        SubtitleDocument Fixture(){var d=SubtitleDocument.New();d.Add(1,2,@"{\i1}甲");d.Add(2.2,3,"乙");d.Add(4,5,"丙");foreach(var r in d.Rows){r.Actor="角色";r.Note="保留";r.Reviewed=true;}return d;}
        void Reject(Action a,string message){bool rejected=false;try{a();}catch(Exception ex) when(ex is InvalidOperationException or FormatException or ArgumentException){rejected=true;}check(rejected,message);}
        var d=Fixture();TimingTools.Shift(d,[0,2],new(.25,false,false,0,0),null);check(d.Rows.First().Start==1.25&&d.Rows.First().End==2.25&&d.Rows.ElementAt(1).Start==2.2&&d.Rows.Last().Start==4.25,"time shift changes disjoint selection only and preserves duration");check(d.Rows.First().Text==@"{\i1}甲"&&d.Rows.All(r=>r.Actor=="角色"&&r.Note=="保留")&&!d.Rows.First().Reviewed&&d.Rows.ElementAt(1).Reviewed,"time shift retains tags actor notes and clears only changed review state");
        foreach(int scope in new[]{0,1,2}){d=Fixture();var rows=TimingTools.Shift(d,[1],new(.1,false,false,scope,0),null);check(rows.Length==(scope==0?1:scope==1?3:2),"shift scope "+scope+" has correct target count");}
        foreach(int fields in new[]{1,2}){d=Fixture();TimingTools.Shift(d,[0],new(.1,false,true,0,fields),null);check(d.Rows.First().Start==(fields==1?.9:1)&&d.Rows.First().End==(fields==2?1.9:2),"shift field "+fields+" preserves opposite endpoint");}
        d=Fixture();string before=d.Serialize();Reject(()=>TimingTools.Shift(d,[0,2],new(1.5,false,true,0,0),null),"negative shift rejects whole batch");check(d.Serialize()==before,"failed shift leaves every row unchanged");
        d=Fixture();TimingTools.Shift(d,[0],new(1.5,false,true,0,0,true),null);check(d.Rows.First().Start==0&&d.Rows.First().End==.5,"explicit negative clipping retains positive remaining duration");
        Reject(()=>TimingTools.Shift(d,[0],new(4,false,true,0,0,true),null),"clipping to zero duration rejected");Reject(()=>TimingTools.Shift(d,[0],new(double.NaN,false,false,0,0),null),"nonfinite shift rejected");Reject(()=>TimingTools.Shift(d,[],new(1,false,false,0,0),null),"empty selection rejected");Reject(()=>TimingTools.Shift(d,[0],new(1,true,false,0,0),null),"frame shift refuses absent frame data");
        var frames=FrameTimeline.Cfr(24,6).WithKeys([0,24,72],"fixture keys");check(frames.Count==144&&frames.At(1.02)==24&&frames.Boundary(25)==1.04,"CFR frame lookup and safe ASS quantization");
        d=Fixture();TimingTools.Shift(d,[0],new(12,true,false,0,0),frames);check(d.Rows.First().Start==1.5&&d.Rows.First().End==2.5,"frame shift moves both endpoints by actual frame indices");
        Reject(()=>TimingTools.Shift(d,[0],new(.5,true,false,0,0),frames),"fractional frame count rejected");Reject(()=>TimingTools.Shift(d,[0],new(200,true,false,0,0),frames),"frame shift outside video rejected");
        var vfr=new FrameTimeline([0,.04,.1,.15,.3,.45],.6,[0,3],"VFR fixture");check(vfr.Shift(.04,2)==.15&&vfr.At(.14)==2,"VFR shift uses explicit timestamps rather than assumed frame rate");check(vfr.Scene(.12)==(0,.15)&&vfr.Scene(.55)==(.15,.6),"scene uses previous key and next exclusive boundary with video-end fallback");
        Reject(()=>new FrameTimeline([0,.1,.1],1,[],"bad"),"duplicate frame timestamps rejected");Reject(()=>new FrameTimeline([0,.1],1,[2],"bad"),"out-of-range keyframe rejected");Reject(()=>FrameTimeline.Cfr(240,1).Boundary(1),"unrepresentable high-rate ASS boundary rejected");Reject(()=>FrameTimeline.ParseV2("# timecode format v1\n0",1),"unsupported timecode format rejected");
        var parsed=FrameTimeline.ParseV2(vfr.Timecodes(),vfr.End).WithKeys(FrameTimeline.ParseKeyframes(vfr.KeyframeText()),"roundtrip");check(parsed.Starts.SequenceEqual(vfr.Starts)&&parsed.Keyframes.SequenceEqual(vfr.Keyframes)&&parsed.End==vfr.End,"timecode v2 and keyframe v1 export/import roundtrip");
        d=Fixture();TimingTools.Align(d,[0,2],2,3.5,null);check(d.Rows.First().Start==.5&&d.Rows.Last().Start==3.5&&d.Rows.First().End==1.5,"align uses active row delta and preserves relative offsets");
        d=Fixture();TimingTools.SnapScene(d,[0,2],frames,1.5);check(d.Rows.First().Start==1&&d.Rows.Last().End==3&&d.Rows.ElementAt(1).Start==2.2,"scene snap applies only selected lines");
        foreach(bool start in new[]{true,false}){d=Fixture();TimingTools.Continuous(d,[0,1,2],start);check(start?d.Rows.ElementAt(1).Start==2&&d.Rows.Last().Start==3&&d.Rows.First().Start==1:d.Rows.First().End==2.2&&d.Rows.ElementAt(1).End==4&&d.Rows.Last().End==5,"contiguous multi-line adjustment changes "+(start?"starts":"ends"));d=Fixture();TimingTools.Continuous(d,[1],start);check(start?d.Rows.ElementAt(1).Start==2&&d.Rows.First().End==2:d.Rows.ElementAt(1).End==4&&d.Rows.Last().Start==4,"single selected line uses unselected neighbor without modifying it");}
        d=Fixture();Reject(()=>TimingTools.Continuous(d,[0,2],true),"disjoint continuity rejects rather than crossing unselected rows");Reject(()=>TimingTools.Continuous(d,[0],true),"first row start continuity rejects missing neighbor");Reject(()=>TimingTools.Continuous(d,[2],false),"last row end continuity rejects missing neighbor");d.Rows.ElementAt(1).End=1.5;before=d.Serialize();Reject(()=>TimingTools.Continuous(d,[0,1],true),"continuity refuses inverted range");check(d.Serialize()==before,"continuity rejection is atomic");
        PostprocessSettings P()=>new(true,["Default"],false,100,false,100,false,300,300,.5,false,100,100,100,100);
        d=Fixture();TimingTools.Postprocess(d,[0,1],P() with{LeadIn=true,LeadOut=true,LeadInMs=200,LeadOutMs=200},null);check(d.Rows.First().Start==.8&&d.Rows.First().End==2&&d.Rows.ElementAt(1).Start==2&&d.Rows.ElementAt(1).End==3.2,"leads extend requested edges without creating new neighboring overlap");
        d=Fixture();TimingTools.Postprocess(d,[0,1],P() with{Continuous=true},null);check(d.Rows.First().End==2.1&&d.Rows.ElementAt(1).Start==2.1,"postprocess closes short gap at bias midpoint");
        d=Fixture();d.Rows.ElementAt(1).Start=1.8;TimingTools.Postprocess(d,[0,1],P() with{Continuous=true,Bias=1},null);check(d.Rows.First().End==1.8&&d.Rows.ElementAt(1).Start==1.8,"postprocess removes short overlap with next-start bias");
        d=Fixture();d.Rows.ElementAt(1).Layer="1";TimingTools.Postprocess(d,[0,1],P() with{Continuous=true},null);check(d.Rows.First().End==2&&d.Rows.ElementAt(1).Start==2.2,"postprocess does not join different layers");
        d=Fixture();d.Rows.ElementAt(1).Style="Other";TimingTools.Postprocess(d,[0,1],P() with{Continuous=true,Styles=["Default","Other"]},null);check(d.Rows.First().End==2&&d.Rows.ElementAt(1).Start==2.2,"postprocess does not join different styles");
        d=Fixture();d.Rows.ElementAt(1).Comment=true;TimingTools.Postprocess(d,[0,1],P() with{LeadIn=true,SelectionOnly=false},null);check(d.Rows.ElementAt(1).Start==2.2&&d.Rows.Last().Start==3.9,"postprocess all scope skips comments");
        d=Fixture();TimingTools.Postprocess(d,[0,2],P() with{Continuous=true,GapMs=2000},null);check(d.Rows.First().End==2&&d.Rows.Last().Start==4,"postprocess cannot bridge unselected intervening line");
        foreach(bool beforeKey in new[]{true,false}){d=Fixture();d.Rows.First().Start=beforeKey?.95:1.05;d.Rows.First().End=beforeKey?2.95:3.05;TimingTools.Postprocess(d,[0],P() with{Snap=true,StartBeforeMs=beforeKey?100:0,StartAfterMs=beforeKey?0:100,EndBeforeMs=beforeKey?100:0,EndAfterMs=beforeKey?0:100},frames);check(d.Rows.First().Start==1&&d.Rows.First().End==3,"separate keyframe start/end "+(beforeKey?"before":"after")+" thresholds work");}
        d=Fixture();Reject(()=>TimingTools.Postprocess(d,[0],P() with{Snap=true},null),"keyframe postprocess requires real data");Reject(()=>TimingTools.Postprocess(d,[0],P(),null),"empty postprocess steps rejected");
        var historyPath=Path.Combine(dir,"shift-history-core.json");var entries=Enumerable.Range(0,25).Select(i=>new ShiftHistoryEntry("字幕.ass",i.ToString(),new(i,false,false,0,0)));TimingTools.WriteHistory(historyPath,entries);check(TimingTools.ReadHistory(historyPath).Count==20,"shift history persists and caps at twenty entries");File.WriteAllText(historyPath,"broken");check(TimingTools.ReadHistory(historyPath).Count==0,"corrupt history does not prevent opening shift tool");
        d=Fixture();var src=d.Rows.First();src.Text=@"{\i1\k20}あ{\kf30}い{\ko50}う";var dst=d.Rows.ElementAt(1);dst.Text=@"{\b1}爱{\b0}情";var sourceBefore=src.Serialize();KanjiTiming.Apply(src,dst,[new(2,1),new(1,1)],false,true);check(dst.Text==@"{\b1}{\k50}爱{\b0}{\k50}情"&&dst.Start==1&&dst.End==2,"kanji transfer supports many-to-one and preserves target static tags");check(src.Serialize()==sourceBefore&&!dst.Reviewed,"kanji transfer does not modify source and clears target review");
        Reject(()=>KanjiTiming.Target(dst.Text,false),"existing target karaoke requires explicit overwrite");check(KanjiTiming.Target(dst.Text,true).Elements.Length==2,"explicit karaoke overwrite strips only timing tags");
        var unicode=KanjiTiming.Target("👩‍💻e\u0301\\N字",false).Elements;check(unicode.Length==4&&unicode[0].Raw=="👩‍💻"&&unicode[1].Raw=="e\u0301"&&unicode[2].Raw==@"\N","kanji target groups Unicode graphemes and ASS line breaks without splitting surrogates");
        src.Text=@"{\k10}{\k40}あ{\k50}い";dst.Text="爱你";check(KanjiTiming.Transfer(src,dst,[new(1,0),new(2,2)],false,"kf")==@"{\kf10}{\kf90}爱你","kanji groups preserve silent durations and many-to-many transfer");
        before=dst.Serialize();Reject(()=>KanjiTiming.Apply(src,dst,[new(1,1)],false,true),"incomplete kanji mapping rejects");check(dst.Serialize()==before,"failed kanji transfer does not partially modify target");Reject(()=>KanjiTiming.Target(@"{\t(0,100,\fs20)}字",false),"animated target rejected instead of corrupting relative effect times");src.Text=@"{\kt5\k10}あ";Reject(()=>KanjiTiming.Parse(src),"absolute karaoke timing explicitly rejected");
        src.Text=@"{\k20}あ{\k-10}い";Reject(()=>KanjiTiming.Parse(src),"invalid embedded source karaoke duration rejected instead of merged");Reject(()=>KanjiTiming.Target(@"{\k1.5}字",true),"invalid fractional target karaoke duration rejected rather than partially removed");
        var native=VideoFrameIndex.Read(Path.Combine(dir,"sample.avi"),CancellationToken.None);File.WriteAllText(Path.Combine(dir,"native-frame-index.txt"),$"Count={native.Count}\nKeys={native.Keyframes.Length}\nEnd={native.End:R}\nFirst={native.Starts[0]:R}\nLast={native.Starts[^1]:R}\nSource={native.Source}\n");check(native.Count==144&&native.Keyframes.Length==144&&Math.Abs(native.End-6)<.001&&Math.Abs(native.Starts[24]-1)<.001,"native Media Foundation indexes actual AVI frames timestamps and clean points");bool cancelled=false;try{VideoFrameIndex.Read(Path.Combine(dir,"sample.avi"),new CancellationToken(true));}catch(OperationCanceledException){cancelled=true;}check(cancelled,"native frame indexing honors cancellation");
    }
}
